namespace {
int checks=0;void check(bool ok,const char* message){++checks;if(!ok)throw std::runtime_error(message);}
template<class F>void reject(F f){bool failed=false;try{f();}catch(...){failed=true;}check(failed,"expected code configuration rejection");}
const ToolResult& result(const CycleResult& c,const QString& id){for(const auto& r:c.tools)if(r.toolId==id)return r;throw std::runtime_error("missing code tool result");}
bool accepted(const CodeResults& codes,const QJsonObject& p){const auto inspection=CodeReadService::inspect(codes,p);return inspection.items[0].accepted && inspection.items[1].accepted;}
}
