    const QString text=QString::fromUtf8("İşlem-Ölçüm")+QChar(0x1d)+"2048";const CodeResult code{text,"QR",text.toUtf8(),{{1,1},{20,1},{20,20},{1,20}}};CodeResults codes{{code}};
