    p=codeReadDefaults();p["rule"]="regex";p["expected"]="[A-Z]+";CodeResults ascii{{{"ABC","Code128","ABC",code.corners}}};check(accepted(ascii,p),"safe regex full match");p["expected"]="[A-Z]{3}";check(accepted(ascii,p),"bounded regex repeat");p["expected"]="(a+)+$";reject([&]{validateCodeRead(p);});p["expected"]="a*a*";reject([&]{validateCodeRead(p);});p["expected"]="a|b";reject([&]{validateCodeRead(p);});p["expected"]="\\1";reject([&]{validateCodeRead(p);});
    p=codeReadDefaults();p["rule"]="exact";p["expected"]="ABC";codes.items.append(ascii.items[0]);check(!accepted(codes,p),"all rejects mismatch");p["selection"]="any";check(accepted(codes,p),"any accepts matching member");p["selection"]="selected";p["selectedIndex"]=1;check(accepted(codes,p),"selected index");p["selectedIndex"]=2;check(!accepted(codes,p),"absent selection false");p=codeReadDefaults();check(!accepted({},p),"default no-read rejects count");p["minCount"]=0;check(accepted({},p),"explicit zero count no-rule policy");p["rule"]="exact";check(!accepted({},p),"empty read never satisfies text rule");
